function Proxy-Present { foreach($k in $ProxyKnown.Keys){ $p=Join-Path $game $k; if((Test-Path $p) -and ($ProxyKnown[$k] -contains (FileSha $p))){ return $true } }; return $false }
function Loader-Ready { return ((Proxy-Present) -and (Test-Path (Join-Path $game 'SAN14Mods\Core\SAN14_ModCore.dll')) -and (Test-Path (Join-Path $game 'SAN14Mods\resolvers\SAN14_Resolver_CEKO.dll'))) }
function Install-Loader {
  # v26k18: the season rules start by themselves (SeasonSync starts them) - the shared mod loader is not needed and not added any more.
  # our old registration in it is removed; a loader an earlier version added is removed only when no other mod uses it.
  $ri=Join-Path $game 'SAN14Mods\modules\SeasonRules.ini'
  if(Test-Path $ri){ $t=Get-Content -LiteralPath $ri -Raw -ErrorAction SilentlyContinue; if($t -match 'SAN14CE\.SeasonRules'){ Remove-Item -Force $ri; Log '예전 모드 로더 등록 정리: SeasonRules.ini (이제 로더 없이 켜집니다)' } }
  Remove-Loader
}
function Remove-Loader {
  $lpf=Join-Path $game ($LoaderMarker+'.pending'); if(Test-Path $lpf){ foreach($r in @(Get-Content -LiteralPath $lpf)){ $p=Join-Path $game $r; if(Test-Path $p){ $ok=$false; foreach($f in $LoaderFiles){ if($f.Rel -eq $r -and (FileSha $p) -eq $f.Sha){ $ok=$true } }; if(-not $ok){ Remove-Item -Force $p } } }; Remove-Item -Force $lpf }
  $mk=Join-Path $game $LoaderMarker; if(-not (Test-Path $mk)){ return }
  $others=@(); $md=Join-Path $game 'SAN14Mods\modules'; if(Test-Path $md){ $others=@(Get-ChildItem $md -Filter '*.ini' -File | Where-Object { $_.Name -ne 'SeasonRules.ini' }) }
  if($others.Count){ Log '모드 로더: 다른 모드가 쓰고 있어 그대로 둡니다.'; Remove-Item -Force $mk; return }
  foreach($l in Get-Content -LiteralPath $mk){ $a=$l.Split('|'); if($a.Count -ne 2){continue}; $p=Join-Path $game $a[0]; if((Test-Path $p) -and (FileSha $p) -eq $a[1]){ Remove-Item -Force $p; Log ('모드 로더 삭제: '+$a[0]) } }
  Remove-Item -Force $mk
}
